from flask import Flask, request, session, redirect, jsonify
import unicodedata

app = Flask(__name__)
app.secret_key = 'shreeramquest'

users = {}

@app.route('/')
def home():
    return "Welcome to ShreeRamQuest! Register or Login"

@app.route('/register', methods=['POST'])
def register():
    data = request.json
    username = data.get('username', '')
    password = data.get('password', '')

    print(f"Registration attempt: {username}")

    # Block "ram"
    username_lower = username.lower()
    if username_lower == "ram":
        return jsonify({"error": "Username 'ram' is not allowed"}), 403

    # Store user
    users[username_lower] = password
    return jsonify({"success": f"Registration successful for: {username}"})

@app.route('/login', methods=['POST'])
def login():
    data = request.json
    username = data.get('username', '')
    password = data.get('password', '')

    print(f"Login attempt: {username}")

    # Block "ram"
    username_lower = username.lower()
    if username_lower == "ram":
        return jsonify({"error": "Username 'ram' is not allowed"}), 403

    # Authenticate
    if username_lower in users and users[username_lower] == password:
        session['username'] = username_lower
        session['authenticated'] = True
        return jsonify({"success": "Login successful", "redirect": f"/profile/{username_lower}"})

    return jsonify({"error": "Invalid credentials"}), 401

@app.route('/profile/<profile>')
def profile(profile):
    if not session.get('authenticated'):
        return jsonify({"error": "You must be logged in to view profiles"}), 401

    print(f"Profile access attempt: {profile}")

    # Convert to lowercase
    profile_lower = profile.lower()

    # Check if accessing "ram"
    if profile_lower == "ram":
        return jsonify({"flag": "csawctf{unicode_normalization_bypass}"})
    # Check if accessing own profile
    elif session['username'] != profile_lower:
        return jsonify({"error": "You can only view your own profile"}), 403

    return jsonify({"success": f"Welcome to your profile, {profile_lower}!"})

@app.route('/test-unicode')
def test_unicode():
    results = []

    # Test different unicode representations
    test_cases = [
        {"name": "Normal RAM", "input": "ram"},
        {"name": "Uppercase RAM", "input": "RAM"},
        {"name": "Mixed case RAM", "input": "RaM"},
        {"name": "Fullwidth R", "input": "ｒam"},
        {"name": "Fullwidth A", "input": "rａm"},
        {"name": "Fullwidth M", "input": "raｍ"},
        {"name": "Circled R", "input": "ⓡam"},
        {"name": "Cyrillic а (looks like a)", "input": "rаm"},
        {"name": "Cyrillic р (looks like p)", "input": "рam"},
        {"name": "Homoglyph r", "input": "ᴦam"},
        {"name": "Zero-width joiner", "input": "r\u200Dam"},
        {"name": "With combining character", "input": "ra\u0304m"},
        {"name": "NFD form", "input": unicodedata.normalize('NFD', "ram")}
    ]

    for case in test_cases:
        input_str = case["input"]
        lower_input = input_str.lower()
        name = case["name"]

        results.append({
            "name": name,
            "input": input_str,
            "unicode_points": [f"U+{ord(c):04X}" for c in input_str],
            "lower_input": lower_input,
            "lower_unicode_points": [f"U+{ord(c):04X}" for c in lower_input],
            "matches_ram": lower_input == "ram",
            "normalized_nfc": unicodedata.normalize('NFC', lower_input),
            "normalized_nfd": unicodedata.normalize('NFD', lower_input),
            "normalized_nfkc": unicodedata.normalize('NFKC', lower_input),
            "normalized_nfkd": unicodedata.normalize('NFKD', lower_input),
        })

    return jsonify(results)

if __name__ == '__main__':
